const normalizeResponse = (data: any, source: string, author: string) => {
  let articles = [];

  switch (source) {
    case 'newsapi':
      articles = data.articles.map((article: any) => ({
        title: article.title,
        description: article.description || 'No description available.',
        url: article.url,
        author: article.author || 'Unknown',
        publishedAt: article.publishedAt,
      }));
      break;

    case 'nytimes':
      articles = data.response.docs.map((article: any) => ({
        title: article.headline?.main || 'No title',
        description: article.abstract || 'No description available.',
        url: article.web_url,
        author: article.byline?.original || 'Unknown', // ✅ Extract author correctly
        publishedAt: article.pub_date || '',
      }));
      break;

    case 'guardian':
      articles = data.response.results.map((article: any) => ({
        title: article.fields?.headline || 'No title',
        description: article.fields?.body?.substring(0, 200) + '...' || 'No description available.',
        url: article.webUrl,
        author: article.fields?.byline || 'Unknown', // ✅ Extract author correctly
        publishedAt: article.fields?.publishedDate || '',
      }));
      break;
  }

  console.log("Fetched Articles:", articles); // ✅ Log articles to check author field

  // ✅ Apply frontend filtering by author
  if (author) {
    articles = articles.filter(article =>
      article.author.toLowerCase().includes(author.toLowerCase())
    );
  }

  return articles;
};
